async function upsertInstance(db, input) {
  const dedupKey = buildDedupKey({
    ruleId: input.rule.id,
    sourceEntityId: input.targetId,
    conditionGeneration: input.generation
  });
  const due = computeDueAt({ rule: input.rule, sourceDateOnly: input.sourceDate.slice(0, 10), timeZone: input.timeZone });
  const existing = await one(
    db,
    "SELECT * FROM reminder_instances WHERE dedup_key = ?",
    dedupKey
  );
  const now2 = nowIso(input.clock.now());
  if (!input.conditionHolds) {
    if (existing && existing.status !== "RESOLVED" && existing.status !== "CANCELLED") {
      await db.prepare("UPDATE reminder_instances SET status = 'RESOLVED', resolved_at = ?, snoozed_until = NULL, last_evaluated_at = ?, updated_at = ? WHERE id = ?").bind(now2, now2, now2, existing.id).run();
    }
    await db.prepare(
      `UPDATE reminder_instances SET status = 'CANCELLED', last_evaluated_at = ?, updated_at = ?
         WHERE rule_id = ? AND target_id = ? AND dedup_key != ? AND status IN ('PENDING','ACTIVE','SNOOZED','ACKNOWLEDGED')`
    ).bind(now2, now2, input.rule.id, input.targetId, dedupKey).run();
    return;
  }
  await cancelOtherGenerations(db, input.rule.id, input.targetId, dedupKey, now2);
  if (!existing) {
    const id = newId();
    const dueIso = due.toISOString();
    const provisional = {
      id,
      ruleId: input.rule.id,
      targetType: input.targetType,
      targetId: input.targetId,
      caseId: input.caseId,
      conditionKey: input.rule.condition,
      generation: input.generation,
      dueAt: dueIso,
      status: "PENDING",
      snoozedUntil: null,
      resolvedAt: null,
      dedupKey
    };
    const initial = evaluateDue({ instance: provisional, conditionHolds: true, clock: input.clock });
    await db.prepare(
      `INSERT INTO reminder_instances (
          id, rule_id, case_id, target_type, target_id, condition_key, generation, due_at, status,
          snoozed_until, resolved_at, last_evaluated_at, dedup_key, owner_user_id, reason, next_action, created_at, updated_at
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, ?, ?, ?, ?, ?, ?, ?)`
    ).bind(
      id,
      input.rule.id,
      input.caseId,
      input.targetType,
      input.targetId,
      input.rule.condition,
      input.generation,
      dueIso,
      initial.status,
      now2,
      dedupKey,
      input.owner,
      input.reason,
      input.nextAction,
      now2,
      now2
    ).run();
    return;
  }
  const evaluated = evaluateDue({
    instance: {
      ...existing,
      dueAt: existing.due_at,
      snoozedUntil: existing.snoozed_until,
      resolvedAt: existing.resolved_at
    },
    conditionHolds: true,
    clock: input.clock
  });
  await db.prepare("UPDATE reminder_instances SET due_at = ?, status = ?, last_evaluated_at = ?, updated_at = ? WHERE id = ?").bind(due.toISOString(), evaluated.status, now2, now2, existing.id).run();
}
async function cancelOtherGenerations(db, ruleId, targetId, dedupKey, now2) {
  await db.prepare(
    `UPDATE reminder_instances SET status = 'CANCELLED', last_evaluated_at = ?, updated_at = ?
       WHERE rule_id = ? AND target_id = ? AND dedup_key != ? AND status IN ('PENDING','ACTIVE','SNOOZED','ACKNOWLEDGED')`
  ).bind(now2, now2, ruleId, targetId, dedupKey).run();
}
async function syncRuleInstances(db, env2, rule, desired) {
  const statements = [];
  if (!rule.enabled) return statements;
  const timeZone = env2.COMPANY_TIMEZONE || "Africa/Cairo";
  const clock2 = systemClock;
  const now2 = nowIso(clock2.now());
  const existing = await all(db, "SELECT id, dedup_key, target_id, status, due_at, snoozed_until, resolved_at FROM reminder_instances WHERE rule_id = ?", rule.id);
  const byKey = new Map(existing.map((row) => [row.dedup_key, row]));
  const openKeysByTarget = /* @__PURE__ */ new Map();
  for (const row of existing) {
    if (row.status === "RESOLVED" || row.status === "CANCELLED") continue;
    const keys = openKeysByTarget.get(row.target_id) ?? /* @__PURE__ */ new Set();
    keys.add(row.dedup_key);
    openKeysByTarget.set(row.target_id, keys);
  }
  for (const item of desired) {
    const generation2 = item.generation || 1;
    const dedupKey = buildDedupKey({ ruleId: rule.id, sourceEntityId: item.targetId, conditionGeneration: generation2 });
    const current = byKey.get(dedupKey);
    const dueIso = computeDueAt({ rule, sourceDateOnly: item.sourceDate.slice(0, 10), timeZone }).toISOString();
    const openKeys = openKeysByTarget.get(item.targetId);
    if (openKeys && [...openKeys].some((key) => key !== dedupKey)) {
      statements.push(
        db.prepare(
          `UPDATE reminder_instances SET status = 'CANCELLED', last_evaluated_at = ?, updated_at = ?
           WHERE rule_id = ? AND target_id = ? AND dedup_key != ? AND status IN ('PENDING','ACTIVE','SNOOZED','ACKNOWLEDGED')`
        ).bind(now2, now2, rule.id, item.targetId, dedupKey)
      );
    }
    if (!item.conditionHolds) {
      if (current && current.status !== "RESOLVED" && current.status !== "CANCELLED") {
        statements.push(
          db.prepare(
            "UPDATE reminder_instances SET status = 'RESOLVED', resolved_at = ?, snoozed_until = NULL, last_evaluated_at = ?, updated_at = ? WHERE id = ?"
          ).bind(now2, now2, now2, current.id)
        );
      }
    } else if (!current) {
      const id = newId();
      const initial = evaluateDue({
        instance: {
          id,
          ruleId: rule.id,
          targetType: item.targetType,
          targetId: item.targetId,
          caseId: item.caseId,
          conditionKey: rule.condition,
          generation: generation2,
          dueAt: dueIso,
          status: "PENDING",
          snoozedUntil: null,
          resolvedAt: null,
          dedupKey
        },
        conditionHolds: true,
        clock: clock2
      });
      statements.push(
        db.prepare(
          `INSERT INTO reminder_instances (
            id, rule_id, case_id, target_type, target_id, condition_key, generation, due_at, status,
            snoozed_until, resolved_at, last_evaluated_at, dedup_key, owner_user_id, reason, next_action, created_at, updated_at
          ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, NULL, NULL, ?, ?, ?, ?, ?, ?, ?)`
        ).bind(
          id,
          rule.id,
          item.caseId,
          item.targetType,
          item.targetId,
          rule.condition,
          generation2,
          dueIso,
          initial.status,
          now2,
          dedupKey,
          item.owner,
          item.reason,
          item.nextAction,
          now2,
          now2
        )
      );
    } else {
      const evaluated = evaluateDue({
        instance: {
          id: current.id,
          ruleId: rule.id,
          targetType: item.targetType,
          targetId: item.targetId,
          caseId: item.caseId,
          conditionKey: rule.condition,
          generation: generation2,
          dueAt: dueIso,
          status: current.status,
          snoozedUntil: current.snoozed_until,
          resolvedAt: current.resolved_at,
          dedupKey
        },
        conditionHolds: true,
        clock: clock2
      });
      statements.push(
        db.prepare("UPDATE reminder_instances SET due_at = ?, status = ?, last_evaluated_at = ?, updated_at = ? WHERE id = ?").bind(
          dueIso,
          evaluated.status,
          now2,
          now2,
          current.id
        )
      );
    }
  }
  if (desired.length > 0) {
    statements.push(
      db.prepare(
        `UPDATE export_cases SET next_action = COALESCE((
           SELECT next_action FROM reminder_instances
           WHERE case_id = export_cases.id AND status IN ('ACTIVE','PENDING','SNOOZED','ACKNOWLEDGED')
           ORDER BY CASE status WHEN 'ACTIVE' THEN 0 WHEN 'PENDING' THEN 1 WHEN 'SNOOZED' THEN 2 ELSE 3 END, due_at
           LIMIT 1
         ), 'No open reminder')
         WHERE id IN (SELECT DISTINCT case_id FROM reminder_instances WHERE rule_id = ?)`
      ).bind(rule.id)
    );
  }
  return statements;
}
